/**
 * Pre-CLI Development Setup Action
 * Combined preCliJSAction for development agents:
 * 1. Moves ticket to In Development status
 * 2. Checks out the feature branch (creating if needed) — ai/<TICKET-KEY>
 * 3. Fetches existing question subtasks with answers into the input folder
 *
 * Used by: story_development.json, test_case_automation.json
 */

var configLoader = require('./configLoader.js');
var prHelper = require('./common/pullRequest.js');
const { GIT_CONFIG, STATUSES, resolveStatuses } = require('./config.js');
const fetchQuestionsToInput = require('./fetchQuestionsToInput.js');
const fetchLinkedTestsToInput = require('./fetchLinkedTestsToInput.js');
const fetchParentContextToInput = require('./fetchParentContextToInput.js');
var restoreFromReleases = require('./restoreFromReleases.js');
var setupCommands = require('./common/setupCommands.js');
var baseBranchMarker = require('./common/baseBranchMarker.js');
var trackersModule = require('./common/trackers.js');
var commentMarkup = require('./common/commentMarkup.js');

// Universal working-directory-aware wrapper for cli_execute_command.
// When config.workingDir is set (via customParams.targetRepository.workingDir),
// all git/shell commands are executed inside that directory.
var _workingDir = null;
function runCmd(args) {
    if (_workingDir) args.workingDirectory = _workingDir;
    return cli_execute_command(args);
}

// Adapter matching the (command, workingDir) signature expected by
// common/pullRequest.js helpers (e.g. ensureRemoteBranchRef) — workingDir is
// captured via the module-level _workingDir closure by runCmd already, so the
// second argument here is accepted but unused.
function runCommandStr(command) {
    return runCmd({ command: command });
}

/**
 * Clean command output from script wrapper artifacts and line-anchored git
 * noise — delegated to the canonical helper (gh-823 one-copy rule; gh-912
 * warning filter lives there once).
 * @param {string} output - Raw command output
 * @returns {string} Cleaned output
 */
function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

function writeBranchConflictGuidance(ticketKey, branchName, baseBranch, details) {
    try {
        file_write({
            path: 'input/' + ticketKey + '/merge_conflicts.md',
            content: '# Branch Conflict Guidance\n\n' +
                'Branch `' + branchName + '` has work that is not already merged into `origin/' + baseBranch + '`, ' +
                'and `origin/' + baseBranch + '` is not an ancestor of this branch.\n\n' +
                'Do not discard the branch work automatically. If a merge conflict appears while syncing with `origin/' + baseBranch + '`, ' +
                'resolve it deliberately. In most cases, prefer `origin/' + baseBranch + '` for repository setup, generated workflow/config files, ' +
                'and shared infrastructure, then re-apply only the ticket-specific implementation that is still relevant.\n\n' +
                'Details:\n\n```\n' + (details || '(not available)') + '\n```\n'
        });
    } catch (e) {
        console.warn('Could not write branch conflict guidance:', e);
    }
}

function branchHasUniquePatches(baseBranch) {
    try {
        var cherry = cleanCommandOutput(runCmd({ command: 'git cherry origin/' + baseBranch + ' HEAD' }) || '');
        if (!cherry.trim()) return false;
        var lines = cherry.split('\n');
        for (var i = 0; i < lines.length; i++) {
            if (lines[i].trim().indexOf('+') === 0) return true;
        }
        return false;
    } catch (e) {
        console.warn('Could not inspect unique branch patches:', e);
        return true;
    }
}

function isAncestorRef(ancestor, descendant) {
    try {
        runCmd({ command: 'git merge-base --is-ancestor ' + ancestor + ' ' + descendant });
        return true;
    } catch (e) {
        return false;
    }
}

function findMergeBase(left, right) {
    try {
        return cleanCommandOutput(runCmd({ command: 'bash agents/scripts/git-merge-base-or-empty.sh ' + left + ' ' + right }) || '');
    } catch (e) {
        return '';
    }
}

function alignBranchWithBase(ticketKey, branchName, baseBranch) {
    if (isAncestorRef('HEAD', 'origin/' + baseBranch)) {
        console.log('Branch changes are already included in origin/' + baseBranch + ', resetting local branch:', branchName);
        runCmd({ command: 'git reset --hard origin/' + baseBranch });
        return;
    }

    if (!branchHasUniquePatches(baseBranch)) {
        console.log('Branch has no unique patches versus origin/' + baseBranch + ', resetting local branch:', branchName);
        runCmd({ command: 'git reset --hard origin/' + baseBranch });
        return;
    }

    if (isAncestorRef('origin/' + baseBranch, 'HEAD')) {
        console.log('Branch already contains origin/' + baseBranch + ':', branchName);
        return;
    }
    console.warn('Branch does not contain origin/' + baseBranch + ':', branchName);

    var details = '';
    try {
        var mergeBase = findMergeBase('HEAD', 'origin/' + baseBranch);
        if (mergeBase) {
            details = cleanCommandOutput(runCmd({ command: 'git merge-tree ' + mergeBase + ' HEAD origin/' + baseBranch }) || '');
        } else {
            details = 'No merge base found between HEAD and origin/' + baseBranch + '. The local checkout is likely shallow or the branch history is unrelated to the current base.';
        }
    } catch (mergeTreeError) {
        details = mergeTreeError && mergeTreeError.toString ? mergeTreeError.toString() : String(mergeTreeError);
    }
    writeBranchConflictGuidance(ticketKey, branchName, baseBranch, details.substring(0, 6000));
    console.warn('Keeping divergent branch ' + branchName + '; conflict guidance written for the agent.');
}

// ── Generated index guard (.codegraph) ──────────────────────────────────────
// `codegraph init/sync` (CI setup step) stages .codegraph/ into the git index.
// If an older run auto-committed that generated index onto the target branch,
// `git checkout <branch>` fails with "Your local changes ... would be
// overwritten". Move the index aside for the duration of branch setup and
// restore it afterwards; if the checked-out branch still tracks .codegraph,
// untrack it so the next auto-commit removes it (self-healing).
// Shell builtins (if/mv/rm/test) are not in the cli_execute_command
// whitelist — wrap them in `bash -c` (whitelisted). IMPORTANT: dmtools'
// shell-metacharacter guard scans the whole string passed to cli_execute_command,
// including the text quoted inside `bash -c "..."` — it does NOT parse quoting,
// so a single `bash -c` call can never contain `;`, `&&`, `||`, `>`/`>>`, etc.,
// even safely inside its own quotes. Every previous attempt at chaining
// if/then/&&/>> inside one bash -c call was silently rejected with
// "disallowed shell metacharacters" on every run, making this guard a no-op.
// Do branching/sequencing in JS instead, and use file_read/file_write (not
// shell grep/printf/>>) for the .gitignore edit.
function commandSucceeds(command) {
    try {
        runCmd({ command: command });
        return true;
    } catch (e) {
        return false;
    }
}

function stashGeneratedIndex() {
    try { runCmd({ command: 'git rm -r --cached --ignore-unmatch .codegraph' }); } catch (e) { }
    if (!commandSucceeds('bash -c "test -d .codegraph"')) return;
    try {
        try { runCmd({ command: 'bash -c "rm -rf .codegraph.branch-setup-bak"' }); } catch (e) { }
        runCmd({ command: 'bash -c "mv .codegraph .codegraph.branch-setup-bak"' });
    } catch (e) {
        console.warn('Could not move .codegraph aside before branch setup:', e);
    }
}

function ensureCodegraphLocalExclude() {
    // .git/info/exclude (not .gitignore): the entry must never reach the
    // target repo's committed files — agents run `git add -A`, and a
    // factory-written .gitignore line would leak into every agent PR.
    try {
        var content = '';
        try { content = file_read({ path: '.git/info/exclude' }) || ''; } catch (e) { content = ''; }
        var lines = content.split('\n');
        var alreadyPre…

/**
 * Pre-CLI Test Rework Setup Action (preCliJSAction for pr_test_automation_rework)
 * Same as preCliReworkSetup.js but specifically targets test/{TICKET-KEY} branches,
 * not feature ai/{TICKET-KEY} branches.
 */

var configLoader = require('./configLoader.js');
const gh = require('./common/githubHelpers.js');
const gitOps = require('./common/gitOps.js');
const prHelper = require('./common/pullRequest.js');
const trackersModule = require('./common/trackers.js');
const fetchQuestionsToInput = require('./fetchQuestionsToInput.js');
const fetchLinkedBugsToInput = require('./fetchLinkedBugsToInput.js');

function findTestPRForTicket(scm, ticketKey) {
    try {
        const branchName = 'test/' + ticketKey;
        console.log('Searching for PR on branch:', branchName);

        const openPRs = scm.listPrs('open');
        const openMatch = openPRs.filter(function(pr) {
            return pr.head && pr.head.ref && pr.head.ref === branchName;
        });
        if (openMatch.length > 0) {
            console.log('Found open test PR #' + openMatch[0].number);
            return openMatch[0];
        }

        console.warn('No open PR found for test branch:', branchName);
        return null;
    } catch (e) {
        console.error('Failed to find test PR:', e);
        return null;
    }
}

function action(params) {
    var tracker = null;
    try {
        var actualParams = params.inputFolderPath ? params : (params.jobParams || params);
        var inputFolder = actualParams.inputFolderPath;
        var ticketKey = inputFolder.split('/').pop();
        var config = configLoader.loadProjectConfig(params.jobParams || params);
        var scm = configLoader.createScm(config);
        tracker = trackersModule.createTracker(config, actualParams.customParams || (params.jobParams && params.jobParams.customParams) || {});

        console.log('=== Test rework setup for:', ticketKey, '===');

        // Clear stale output files from any previous run so the post-action
        // never reads a result JSON that belongs to a different ticket.
        try {
            cli_execute_command({
                command: 'bash -c "rm -f outputs/test_automation_result.json outputs/story_test_automation_result.json outputs/tracker_comment.md outputs/comment.md outputs/jira_comment.md outputs/response.md outputs/pr_body.md outputs/bug_description.md outputs/failed_description_*.md"'
            });
            console.log('Cleared stale output files before rework');
        } catch (e) {
            console.warn('Could not clear output files:', e);
        }

        // Step 1: GitHub repo info
        var repoInfo = scm.getRemoteRepoInfo();
        if (!repoInfo) {
            const err = 'Could not determine GitHub repository from git remote';
            try { tracker.postComment(ticketKey, 'h3. ❌ Test Rework Setup Failed\n\n' + err); } catch (e) {}
            return { success: false, error: err };
        }

        // Step 2: Find PR on test/{KEY} branch specifically
        var pr = findTestPRForTicket(scm, ticketKey);
        const testBranchName = 'test/' + ticketKey;

        if (!pr) {
            // No open PR — check if the test branch exists on remote
            console.log('No open PR found. Checking if branch exists on remote:', testBranchName);
            var branchExists = false;
            try {
                const lsOutput = cli_execute_command({ command: 'git ls-remote --heads origin ' + testBranchName }) || '';
                branchExists = lsOutput.indexOf('refs/heads/' + testBranchName) !== -1;
            } catch (e) {
                console.warn('Could not check remote branch:', e);
            }

            if (!branchExists) {
                const err = 'No test PR and no remote branch found for ' + testBranchName + '. Moving to Backlog for re-automation.';
                try {
                    tracker.postComment(ticketKey, 'h3. ❌ Test Rework Setup Failed\n\n' + err);
                    tracker.moveToStatus(ticketKey, config.jira.statuses.BACKLOG);
                } catch (e) {}
                return { success: false, error: err };
            }

            // Branch exists — ALWAYS checkout first so CLI runs on correct branch
            // (critical: CLI always runs regardless of preCliJSAction return value)
            try {
                gitOps.checkoutPRBranch(testBranchName, config.workingDir, config.git.baseBranch);
                console.log('✅ Checked out branch:', testBranchName);
            } catch (e) {
                console.warn('Could not checkout branch (will try fetch+checkout):', e);
                try {
                    cli_execute_command({ command: gh.buildOriginFetchCommand(testBranchName + ':' + testBranchName) });
                    cli_execute_command({ command: 'git checkout ' + testBranchName });
                    console.log('✅ Checked out branch via fetch:', testBranchName);
                } catch (e2) {
                    console.warn('Branch checkout failed:', e2);
                }
            }

            console.log('Creating PR for rework from existing branch...');
            try {
                const ticket = tracker.getIssue(ticketKey);
