            '⚠️ *Merge conflicts detected* — ' + conflictFiles.length + ' file(s) must be resolved:\n' +
            conflictFiles.map(function(f) { return '* {code}' + f + '{code}'; }).join('\n') +
            '{panel}\n\n';
    }

