    return { success: false, error: error };
}

function buildSuccessResult(prDetails, branchName, repoInfo) {
    return {
        success: true,
        prNumber: prDetails.number,
        prUrl: prDetails.html_url,
        branchName: branchName,
        owner: repoInfo.owner,
        repo: repoInfo.repo
