        tracker = createErrorTracker(params, tracker);
        const ticketKey = parseErrorTicketKey(params);
        if (ticketKey) {
            tracker.postComment(ticketKey, 'h3. ❌ Test Rework Setup Error\n\n{code}' + error.toString() + '{code}');
        }
